class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        words = set(dictionary)
        dp = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            best = dp[i + 1] + 1
            for w in words:
                L = len(w)
                if i + L <= n and s[i:i + L] == w:
                    best = min(best, dp[i + L])
            dp[i] = best
        return dp[0]
