    return json.dumps(s) + "\n" + json.dumps(words) + "\n"

def validate(inp):
    try:
        lines = [l for l in inp.split("\n") if l.strip() != ""]
        if len(lines) != 2:
            return False
        s = json.loads(lines[0])
        d = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(s, str) or not (1 <= len(s) <= 50):
        return False
    if not all(c in "abcdefghijklmnopqrstuvwxyz" for c in s):
        return False
    if not isinstance(d, list) or not (1 <= len(d) <= 50):
        return False
    for w in d:
        if not isinstance(w, str) or not (1 <= len(w) <= 50):
            return False
        if not all(c in "abcdefghijklmnopqrstuvwxyz" for c in w):
            return False
    if len(set(d)) != len(d):
        return False
    return True

def ref(inp):
    lines = [l for l in inp.split("\n") if l.strip() != ""]
    s = json.loads(lines[0])
    d = json.loads(lines[1])
    n = len(s)

    # f(i) = minimum extra characters in suffix s[i:], by the literal definition:
    # either s[i] is an extra character, or a dictionary word starts at i and is used.
    def f(i):
        if i == n:
            return 0
        best = 1 + f(i + 1)
        for w in d:
            if s.startswith(w, i):
                best = min(best, f(i + len(w)))
        return best

    return json.dumps(f(0))
